function childrenText(text, from, closeTag) {
  const end = text.indexOf(closeTag, from);
  if (end < 0) return { text: "", end: from };
  const inner = text.slice(from, end);
  const plain = inner
    .replace(/<[^>]*>/g, " ")
    .replace(/\{["'`]([^"'`]*)["'`]\}/g, "$1")
    .replace(/\{[^}]*\}/g, " ")
    .replace(/\s+/g, " ")
    .trim();
